    }
    $childHash = (Get-FileHash -LiteralPath $child -Algorithm SHA256).Hash
    $measurementHash = (Get-FileHash -LiteralPath $measurement -Algorithm SHA256).Hash

    $start = [Diagnostics.ProcessStartInfo]::new('dotnet')
