        ActualMeanNs=(($actualRows | ForEach-Object {$_.TotalNanoseconds/4} | Measure-Object -Average).Average)
        ActualIterations=@($actualRows | ForEach-Object {[ordered]@{BdnNanoseconds=$_.TotalNanoseconds;Operations=$_.Operations;NsPerOperation=($_.TotalNanoseconds/4)}})
        ResultIterations=@($resultRows | ForEach-Object {[ordered]@{BdnNanoseconds=$_.TotalNanoseconds;Operations=$_.Operations;NsPerOperation=($_.TotalNanoseconds/4)}})
        ActualCount=$actualRows.Count; ResultCount=$resultRows.Count; WarmupCount=16
        AllocatedBytesPerOperation=([long]$gc.Groups['bytes'].Value/[long]$gc.Groups['ops'].Value)
        GC=@([int]$gc.Groups['g0'].Value,[int]$gc.Groups['g1'].Value,[int]$gc.Groups['g2'].Value)
        Runtime=([regex]::Match($stdout,'(?m)^// Runtime=(?<v>.+)$').Groups['v'].Value)
        BenchmarkDotNet=([regex]::Match($stdout,'(?m)^// BenchmarkDotNet v(?<v>\S+)').Groups['v'].Value)
        Job=([regex]::Match($stdout,'(?m)^// Job: (?<v>.+)$').Groups['v'].Value)
        TieredPGO=1; Affinity=4; ProcessId=$processId; ExitCode=$exitCode; StartUTC=$startedUtc.ToString('o'); EndUTC=$endedUtc.ToString('o'); WallSeconds=$watch.Elapsed.TotalSeconds; InputBytes=(Get-Item $inputPath).Length; InputSHA256=$expectedInputHash
        AssemblySHA256=$childHash; MeasurementHostAssemblySHA256=$measurementHash
