$stdoutTask = $process.StandardOutput.ReadToEndAsync()
$stderrTask = $process.StandardError.ReadToEndAsync()
$startedUtc = [DateTime]::UtcNow
$watch = [Diagnostics.Stopwatch]::StartNew()
try {
    while (-not $process.WaitForExit(1000)) {
        if ($watch.Elapsed.TotalSeconds -gt 180) { $process.Kill($true); throw 'JIT diagnostic timed out after 180 seconds.' }
    }
    $exitCode = $process.ExitCode
    $endedUtc = [DateTime]::UtcNow
    $stdout = $stdoutTask.GetAwaiter().GetResult()
    $stderr = $stderrTask.GetAwaiter().GetResult()
    [IO.File]::WriteAllText((Join-Path $runRoot 'stdout.log'),$stdout,[Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $runRoot 'stderr.log'),$stderr,[Text.UTF8Encoding]::new($false))
    if ($exitCode -ne 0) { throw "JIT diagnostic exit code $exitCode; raw output retained." }
    if ($stderr.Trim().Length -ne 0) { throw 'JIT diagnostic wrote to stderr; raw output retained.' }
    if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw 'Missing // AfterAll completion marker.' }
    $actualCount = [regex]::Matches($stdout,'(?m)^WorkloadActual\s+\d+:').Count
    $resultCount = [regex]::Matches($stdout,'(?m)^WorkloadResult\s+\d+:').Count
    $asmPath = Join-Path $runRoot 'jit.asm'
    if (-not (Test-Path -LiteralPath $asmPath)) { throw 'JIT disassembly file was not produced.' }
    $asm = [IO.File]::ReadAllText($asmPath)
    $headers = [regex]::Matches($asm,'(?m)^; Assembly listing for method .+$')
    $targetHeaders = @($headers | Where-Object Value -Match 'WithWhiteSpace')
    $record = [ordered]@{
        Variant=$Variant; ProcessId=$processId; ExitCode=$exitCode
        StartUTC=$startedUtc.ToString('o'); EndUTC=$endedUtc.ToString('o'); WallSeconds=$watch.Elapsed.TotalSeconds
        Affinity=4; TieredPGO=1; JitDisasm='Marimo.*!*'; JitDisasmWithCodeBytes=1
        ActualCount=$actualCount; ResultCount=$resultCount
        InputBytes=(Get-Item -LiteralPath $input).Length; InputSHA256=(Get-FileHash -LiteralPath $input -Algorithm SHA256).Hash
        LibrarySHA256=(Get-FileHash -LiteralPath $library -Algorithm SHA256).Hash
        ParserSHA256=(Get-FileHash -LiteralPath (Join-Path $hostRoot 'Marimo.Parser.dll') -Algorithm SHA256).Hash
        DLLManifestSHA256=(Get-FileHash -LiteralPath (Join-Path $root 'dll-manifest.json') -Algorithm SHA256).Hash
        JitOutputBytes=(Get-Item -LiteralPath $asmPath).Length; JitOutputSHA256=(Get-FileHash -LiteralPath $asmPath -Algorithm SHA256).Hash
        AssemblyMethodHeaderCount=$headers.Count; WithWhiteSpaceMethodHeaderCount=$targetHeaders.Count
        WithWhiteSpaceHeaders=@($targetHeaders | ForEach-Object Value)
        DiagnosticOnly=$true; OutputFiles=@('jit.asm','stdout.log','stderr.log')
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runRoot 'capture.json') -Encoding utf8
    if ($actualCount -ne 8 -or $resultCount -ne 8) { throw "Expected 8 Actual and 8 Result windows; got $actualCount/$resultCount." }
    if ($targetHeaders.Count -eq 0) { throw 'No WithWhiteSpace method was emitted in JIT output.' }
    Write-Output ($record | ConvertTo-Json -Compress)
} finally {
    if (-not $process.HasExited) { $process.Kill($true); $process.WaitForExit() }
    $process.Dispose()
}

EvidenceBuilder.Body:
# Assemble a hash-linked, replayable evidence record for the JSON whitespace predicate experiment.
param([switch]$RefreshPowerHelperRelease)

$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$repo = (Resolve-Path (Join-Path $root '../..')).Path
$output = Join-Path $repo 'Kotowari.Benchmarks/Results/experiments/2026-10-19-whitespace-predicate.json'

function Read-Json([string]$Path) {
    Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -DateKind String
}

function Get-Hash([string]$Path) {
    (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash
}

function Get-RelativePath([string]$Path) {
    [IO.Path]::GetRelativePath($repo, $Path).Replace('\', '/')
}

function Get-Tier1Method([string]$Path, [string]$Pattern, [int]$ExcerptLength = 80) {
    $lines = [IO.File]::ReadAllLines($Path)
    $startIndex = -1
    for ($index = 0; $index -lt $lines.Length; $index++) {
        if ($lines[$index] -match $Pattern) { $startIndex = $index }
    }
    if ($startIndex -lt 0) { throw "JIT Tier1 method was not found: $Pattern" }
    $endIndex = $startIndex + 1
    while ($endIndex -lt $lines.Length -and $lines[$endIndex] -notmatch '^; Assembly listing for method') { $endIndex++ }
    $methodLines = @($lines[$startIndex..($endIndex - 1)])
    $byteLine = $methodLines | Select-String 'Total bytes of code (?<bytes>\d+)' | Select-Object -Last 1
    if (-not $byteLine) { throw "JIT code-size line was not found: $Pattern" }
    [ordered]@{
        HeaderLine = $startIndex + 1
        CodeBytes = [int]$byteLine.Matches[0].Groups['bytes'].Value
        Header = $lines[$startIndex]
        Excerpt = @($methodLines | Select-Object -First $ExcerptLength)
        ExcerptLineCount = [Math]::Min($ExcerptLength, $methodLines.Count)
    }
}

function Get-PairedSummary([string]$Batch) {
    $batchRoot = Join-Path $root "runs/$Batch"
    $runs = @(
        foreach ($block in 1..8) {
            foreach ($variant in @('baseline', 'candidate')) {
                $runName = '{0:d2}-{1}' -f $block, $variant
                $runDirectory = Join-Path $batchRoot $runName
                $summaryPath = Join-Path $runDirectory 'run-summary.json'
                if (-not (Test-Path -LiteralPath $summaryPath)) { throw "Missing completed run: $Batch/$runName" }
                $summary = Read-Json $summaryPath
                if ($summary.Run -ne $runName -or $summary.Batch -ne $Batch -or $summary.Variant -ne $variant) { throw "Run identity mismatch: $Batch/$runName" }
                if ($summary.ExitCode -ne 0 -or $summary.ProcessId -eq $null -or $summary.ActualCount -ne 8 -or $summary.ResultCount -ne 8 -or $summary.WarmupCount -ne 16) { throw "Run status/window mismatch: $Batch/$runName" }
                if (@($summary.ActualIterations).Count -ne 8 -or @($summary.ResultIterations).Count -ne 8 -or @($summary.ActualIterations + $summary.ResultIterations | Where-Object Operations -ne 4).Count -ne 0) { throw "Actual/Result invocation mismatch: $Batch/$runName" }
                if ($summary.InputBytes -ne 4172062 -or $summary.InputSHA256 -ne 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D' -or $summary.LibraryDLLSHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw "Input/core hash mismatch: $Batch/$runName" }
                if ($summary.DLLManifestSHA256 -ne (Get-Hash (Join-Path $root 'dll-manifest.json'))) { throw "DLL manifest hash mismatch: $Batch/$runName" }
                $expectedParser = if ($variant -eq 'baseline') { '1075799C05DC787D354EFC931D3A641C5C4424561F91C401947DB8D018CA0ACB' } else { 'BAD351B1D5A6673C2096A4D0C2E04C4C2743B73EBAF70E1135890AF9504F4418' }
                $manifest = Read-Json (Join-Path $root 'dll-manifest.json')
                if (($manifest.$variant | Where-Object Name -eq 'Marimo.Parser.dll').SHA256 -ne $expectedParser) { throw "Parser hash mismatch in manifest: $Batch/$runName" }
                $hostLogPath = Join-Path $runDirectory $summary.HostLog
                $stderrPath = Join-Path $runDirectory $summary.Stderr
                if (-not (Test-Path -LiteralPath $hostLogPath) -or -not (Test-Path -LiteralPath $stderrPath)) { throw "Raw host output is missing: $Batch/$runName" }
                $hostLog = [IO.File]::ReadAllText($hostLogPath)
                $stderrText = [IO.File]::ReadAllText($stderrPath)
                if ($stderrText.Length -ne 0 -or $hostLog -notmatch '(?m)^// AfterAll\s*$') { throw "Raw host output status mismatch: $Batch/$runName" }
                [ordered]@{
                    Name = $runName
                    SummaryPath = Get-RelativePath $summaryPath
                    SummarySHA256 = Get-Hash $summaryPath
                    Summary = $summary
                    HostLogPath = Get-RelativePath $hostLogPath
                    HostLogSHA256 = Get-Hash $hostLogPath
                    HostLog = $hostLog
                    StderrPath = Get-RelativePath $stderrPath
                    StderrSHA256 = Get-Hash $stderrPath
                    Stderr = $stderrText
                    ParserDLLSHA256 = $expectedParser
                }
            }
        }
    )
    if ($runs.Count -ne 16) { throw "Expected 16 successful process launches in $Batch." }
    $pairs = @(
        foreach ($block in 1..8) {
            $baseline = Read-Json (Join-Path $batchRoot ('{0:d2}-baseline/run-summary.json' -f $block))
            $candidate = Read-Json (Join-Path $batchRoot ('{0:d2}-candidate/run-summary.json' -f $block))
            $ratio = [double]$candidate.MeanNs / [double]$baseline.MeanNs
            [ordered]@{
                Block = $block
                Order = if ($block % 2) { 'baseline-candidate' } else { 'candidate-baseline' }
                BaselineMeanNs = [double]$baseline.MeanNs
                CandidateMeanNs = [double]$candidate.MeanNs
                CandidateOverBaseline = $ratio
                LogCandidateOverBaseline = [math]::Log($ratio)
                BaselineAllocatedBytesPerOperation = [double]$baseline.AllocatedBytesPerOperation
                CandidateAllocatedBytesPerOperation = [double]$candidate.AllocatedBytesPerOperation
            }
        }
    )
    $logs = @($pairs | ForEach-Object LogCandidateOverBaseline)
    $meanLog = ($logs | Measure-Object -Average).Average
    $sumSquares = 0.0
    foreach ($value in $logs) { $sumSquares += [math]::Pow($value - $meanLog, 2) }
    $sdLog = [math]::Sqrt($sumSquares / 7)
    $seLog = $sdLog / [math]::Sqrt(8)
    $critical = 2.364624251
    $saved = Read-Json (Join-Path $root "$Batch-summary.json")
    $geometricRatio = [math]::Exp($meanLog)
    $lower = [math]::Exp($meanLog - $critical * $seLog)
    $upper = [math]::Exp($meanLog + $critical * $seLog)
    if ([math]::Abs($geometricRatio - $saved.PairedGeometricMeanRatio) -gt 1e-12 -or [math]::Abs($lower - $saved.Confidence95.Lower) -gt 1e-12 -or [math]::Abs($upper - $saved.Confidence95.Upper) -gt 1e-12) { throw "Saved summary differs from recomputation: $Batch" }
    [ordered]@{
        Batch = $Batch
        PairCount = 8
        DegreesOfFreedom = 7
        TCritical95Df7 = $critical
        PairedLogRatioMean = $meanLog
        PairedLogRatioSampleStandardDeviation = $sdLog
        PairedLogRatioStandardError = $seLog
        PairedGeometricMeanRatio = $geometricRatio
        Confidence95 = [ordered]@{ Lower = $lower; Upper = $upper }
        BaselineMeanMsPerParse = (($pairs.BaselineMeanNs | Measure-Object -Average).Average / 1e6)
        CandidateMeanMsPerParse = (($pairs.CandidateMeanNs | Measure-Object -Average).Average / 1e6)
        BaselineMeanAllocatedBytesPerParse = (($pairs.BaselineAllocatedBytesPerOperation | Measure-Object -Average).Average)
        CandidateMeanAllocatedBytesPerParse = (($pairs.CandidateAllocatedBytesPerOperation | Measure-Object -Average).Average)
        Pairs = $pairs
        Runs = $runs
        SummaryPath = Get-RelativePath (Join-Path $root "$Batch-summary.json")
        SummarySHA256 = Get-Hash (Join-Path $root "$Batch-summary.json")
        SavedSummary = $saved
    }
}

function Get-Scripts {
    $scriptPaths = @(
        'Build-Evidence.ps1', 'Freeze-DllManifest.ps1', 'Validate-Host.ps1', 'Write-SourceManifest.ps1',
        'scripts/Run-Block.ps1', 'scripts/Summarize.ps1', 'scripts/Record-Environment.ps1',
        'scripts/Test-PowerReadiness.ps1', 'scripts/Run-JitDiagnostic.ps1'
    )
    @(
        foreach ($relative in $scriptPaths) {
            $path = Join-Path $root $relative
            [ordered]@{ Name = Split-Path -Leaf $relative; Path = $relative; SHA256 = Get-Hash $path; Body = [IO.File]::ReadAllText($path) }
        }
    )
}

if ($RefreshPowerHelperRelease) {
    if (-not (Test-Path -LiteralPath $output)) { throw "Cannot refresh power-helper release before evidence exists: $output" }
    $existing = Read-Json $output
    $repoRoot = (Resolve-Path (Join-Path $root '../..')).Path
    $helperRoot = Join-Path $repoRoot 'artifacts/string-recursive-definition-2026-10-19/power-02'
    $statusPath = Join-Path $helperRoot 'power-helper-status.json'
    $heartbeatPath = Join-Path $helperRoot 'power-helper-heartbeat.jsonl'
    if (-not (Test-Path -LiteralPath $statusPath) -or -not (Test-Path -LiteralPath $heartbeatPath)) { throw 'Power helper stop evidence is missing.' }
    $status = Read-Json $statusPath
    $heartbeats = @(Get-Content -LiteralPath $heartbeatPath | ForEach-Object { $_ | ConvertFrom-Json -DateKind String })
    if ($status.Reason -ne 'StopFile' -or -not $status.StoppedUtc -or [long]$status.ReleaseReturn -ne 2147483649 -or $status.Error -ne $null -or $status.ThreadId -ne $status.FinalThreadId) { throw 'Power helper release status is incomplete or unsuccessful.' }
    if ($heartbeats.Count -eq 0) { throw 'Power helper heartbeat evidence is empty.' }
    if (Get-Process -Id ([int]$status.Pid) -ErrorAction SilentlyContinue) { throw 'Power helper process is still active.' }
    if (@($heartbeats | Where-Object { [DateTimeOffset]::Parse($_.Utc) -gt [DateTimeOffset]::Parse($status.StoppedUtc) }).Count -gt 0) { throw 'Heartbeat records exist after the recorded stop time.' }
    $existing.Environment.PowerHelper.Release = [ordered]@{
        StatusPath = Get-RelativePath $statusPath
        StatusSHA256 = Get-Hash $statusPath
        Status = $status
        HeartbeatPath = Get-RelativePath $heartbeatPath
        HeartbeatSHA256 = Get-Hash $heartbeatPath
        HeartbeatCount = $heartbeats.Count
        LastHeartbeatUTC = $heartbeats[-1].Utc
        StoppedUTC = $status.StoppedUtc
        ReleaseReturn = $status.ReleaseReturn
        HelperPidExited = $true
        FinalThreadId = $status.FinalThreadId
        RecordedAfterMeasurement = $true
        Released = $true
    }
    $existing.Environment.Interpretation = 'Before/after records for both batches show AC power, Battery Saver off, and no active dotnet CPU process. The shared system-required helper remained active through measurement and was then released successfully; its process exited and no heartbeat was recorded after the stop time.'
    $builderText = [IO.File]::ReadAllText($PSCommandPath)
    $builderHash = Get-Hash $PSCommandPath
    $existing.Replay.EvidenceBuilder.SHA256 = $builderHash
    $existing.Replay.EvidenceBuilder.Body = $builderText
    foreach ($script in $existing.Replay.Scripts) {
        if ($script.Path -eq 'Build-Evidence.ps1') { $script.SHA256 = $builderHash; $script.Body = $builderText }
    }
    $existingJson = ConvertTo-Json -InputObject $existing -Depth 50
    if ($existingJson -match '(?i)[A-Z]:\\Users\\|[A-Z]:/Users/') { throw 'Evidence content contains a user-specific absolute path.' }
    $savedText = ($existingJson -replace "`r?`n", "`r`n") + "`r`n"
    $utf8 = [Text.UTF8Encoding]::new($true)
    [IO.File]::WriteAllBytes($output, $utf8.GetPreamble() + $utf8.GetBytes($savedText))
    Write-Output ([ordered]@{ Path = Get-RelativePath $output; SHA256 = Get-Hash $output; PowerHelperReleased = $true } | ConvertTo-Json -Compress)
    exit 0
}

if (Test-Path -LiteralPath $output) { throw "Refusing to overwrite existing evidence: $output" }
$inputPath = Join-Path $root 'baseline/host/Data/test.json'
$inputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
if ((Get-Item -LiteralPath $inputPath).Length -ne 4172062 -or (Get-Hash $inputPath) -ne $inputHash) { throw 'Frozen benchmark input mismatch.' }
$baselineSource = Read-Json (Join-Path $root 'baseline/source-manifest.json')
$candidateSource = Read-Json (Join-Path $root 'candidate/source-manifest.json')
if ($baselineSource.HEAD -ne 'd2f7aa8915ca1f580fc009b0a5d88d7b3c9d1ec1' -or $candidateSource.HEAD -ne $baselineSource.HEAD -or $baselineSource.SourceFiles.Count -ne 43 -or $candidateSource.SourceFiles.Count -ne 43) { throw 'Source snapshot identity or count mismatch.' }
$sourceDifferences = @(
    foreach ($file in $baselineSource.SourceFiles) {
        $candidateFile = $candidateSource.SourceFiles | Where-Object Path -eq $file.Path
        if (-not $candidateFile -or $candidateFile.SHA256 -ne $file.SHA256) { $file.Path }
    }
)
if ($sourceDifferences.Count -ne 1 -or $sourceDifferences[0] -ne 'JsonParser/JSON.cs') { throw "Unexpected source differences: $($sourceDifferences -join ', ')" }
$dllManifestPath = Join-Path $root 'dll-manifest.json'
$dllManifest = Read-Json $dllManifestPath
if ($dllManifest.baseline.Count -ne 28 -or $dllManifest.candidate.Count -ne 28) { throw 'Expected 28 frozen DLLs per host.' }
foreach ($variant in 'baseline', 'candidate') {
    if (($dllManifest.$variant | Where-Object Name -eq 'Marimo.Kotowari.dll').SHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw "$variant fixed core-library hash mismatch." }
}
$dllDifferences = @(
    foreach ($dll in $dllManifest.baseline) {
        $candidateDll = $dllManifest.candidate | Where-Object Name -eq $dll.Name
        if (-not $candidateDll -or $candidateDll.SHA256 -ne $dll.SHA256) { $dll.Name }
    }
)
if ($dllDifferences.Count -ne 1 -or $dllDifferences[0] -ne 'Marimo.Parser.dll') { throw "Unexpected DLL differences: $($dllDifferences -join ', ')" }
foreach ($variant in 'baseline', 'candidate') {
    foreach ($dll in $dllManifest.$variant) {
        if ((Get-Hash (Join-Path $root "$variant/host/$($dll.Name)")) -ne $dll.SHA256) { throw "Frozen host DLL changed: $variant/$($dll.Name)" }
    }
}
foreach ($variant in 'baseline', 'candidate') {
    $validation = Read-Json (Join-Path $root "$variant/validation.json")
    if ($validation.ExitCode -ne 0 -or $validation.InputBytes -ne 4172062 -or $validation.InputSHA256 -ne $inputHash -or $validation.FullInputConsumed -ne $true -or $validation.ExpectedNodeCount -ne 100001 -or -not $validation.SystemTextJsonTreeEquivalent -or $validation.LibrarySHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw "$variant validation failed or is incomplete." }
}
$parentValidationPath = Join-Path $root 'parent-validation.json'
$parentValidation = Read-Json $parentValidationPath
if ($parentValidation.Build.ExitCode -ne 0 -or $parentValidation.AllTests.ExitCode -ne 0 -or $parentValidation.AllTests.Passed -ne 311 -or $parentValidation.AllTests.Failed -ne 0 -or $parentValidation.Format.CurrentDiagnosticCount -ne 66 -or $parentValidation.Format.PreviousDiagnosticCount -ne 66 -or $parentValidation.Format.ChangedLinesHaveNewDiagnostics) { throw 'Parent build/test/format verification did not meet its recorded conditions.' }
$patchPath = Join-Path $root 'candidate.patch'
$patchText = [IO.File]::ReadAllText($patchPath)
if ([regex]::Matches($patchText, '(?m)^diff --git ').Count -ne 2 -or $patchText -notmatch 'ConditionalCharParser' -or $patchText -notmatch '四種類の空白が混在') { throw 'Candidate patch does not contain the implementation and six characterization cases.' }

$exploration = Get-PairedSummary 'exploration'
$confirmation = Get-PairedSummary 'confirmation'
if ($exploration.Confidence95.Upper -ge 1 -or $confirmation.Confidence95.Upper -ge 1) { throw 'The predeclared two-stage adoption rule is not satisfied.' }
$environmentPath = Join-Path $root 'environment.json'
$environment = @(Read-Json $environmentPath)
$expectedStages = @('before', 'after', 'confirmation-before', 'confirmation-after')
foreach ($stage in $expectedStages) {
    $record = $environment | Where-Object Stage -eq $stage
    if (-not $record -or $record.ACLineStatus -ne 1 -or $record.BatterySaver -ne 0 -or @($record.ActiveDotnetProcesses).Count -ne 0) { throw "Power/environment record missing or invalid: $stage" }
}
$helperRepo = (Resolve-Path (Join-Path $root '../..')).Path
$helperRoot = Join-Path $helperRepo 'artifacts/string-recursive-definition-2026-10-19/power-02'
$helperStatusPath = Join-Path $helperRoot 'power-helper-status.json'
$helperHeartbeatPath = Join-Path $helperRoot 'power-helper-heartbeat.jsonl'
$helperStatus = Read-Json $helperStatusPath
$helperHeartbeats = @(Get-Content -LiteralPath $helperHeartbeatPath | ForEach-Object { $_ | ConvertFrom-Json -DateKind String })
if ($helperStatus.Reason -ne 'Running' -or [long]$helperStatus.AcquireReturn -ne 2147483648 -or $helperStatus.CurrentPower.ACLineStatus -ne 1 -or $helperStatus.CurrentPower.BatterySaver) { throw 'Shared power helper is not confirmed active.' }

$jitRecords = [ordered]@{}
foreach ($variant in 'baseline', 'candidate') {
    $captureRoot = Join-Path $root "diagnostics/jit/$variant/capture-01"
    $capturePath = Join-Path $captureRoot 'capture.json'
    $capture = Read-Json $capturePath
    if ($capture.ExitCode -ne 0 -or $capture.ActualCount -ne 8 -or $capture.ResultCount -ne 8 -or -not $capture.DiagnosticOnly -or $capture.LibrarySHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw "JIT diagnostic integrity mismatch: $variant" }
    $asmPath = Join-Path $captureRoot 'jit.asm'
    $whitespace = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Kotowari\.WithWhiteSpaceParser`1\[char\]:ParseCore.*\(Tier1\)$' 95
    $predicate = $null
    if ($variant -eq 'candidate') { $predicate = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Parser\.JSON\+<>c:<\.cctor>b__37_0\(char\):bool:this \(Tier1\)$' 50 }
    $jitRecords[$variant] = [ordered]@{
        Capture = $capture
        CapturePath = Get-RelativePath $capturePath
        CaptureSHA256 = Get-Hash $capturePath
        AssemblyPath = Get-RelativePath $asmPath
        AssemblySHA256 = Get-Hash $asmPath
        AssemblyBytes = (Get-Item -LiteralPath $asmPath).Length
        WithWhiteSpaceTier1 = $whitespace
        PredicateTier1 = $predicate
    }
}
$builderText = [IO.File]::ReadAllText($PSCommandPath)
$replayScripts = Get-Scripts
$data = [ordered]@{
    Schema = 'kotowari-json-whitespace-predicate-evidence-v1'
    Experiment = '2026-10-19-whitespace-predicate'
    Decision = [ordered]@{
        Status = 'Confirmation supports adoption under the predeclared gate; implementation remains uncommitted.'
        Rule = 'Run an independent eight-pair confirmation only when exploration 95% paired log-t interval upper bound is below 1. Candidate adoption requires confirmation upper bound below 1 as well.'
        ExplorationGatePassed = $true
        ConfirmationGatePassed = $true
        Interpretation = 'The measured workload is full-file JSON StringInput parsing with the frozen 4,172,062-byte sample. Results support an improvement on this machine and setup; they do not establish general performance across other inputs or environments.'
    }
    Change = [ordered]@{
        BaselineCommit = $baselineSource.HEAD
        Description = 'Replace the four fixed CharParser alternatives for JSON whitespace with the existing ConditionalCharParser matching exactly SPACE, TAB, CR and LF. No library/public API change.'
        SourceFiles = [ordered]@{ Baseline = $baselineSource.SourceFiles; Candidate = $candidateSource.SourceFiles; BaselineCount = $baselineSource.SourceFiles.Count; CandidateCount = $candidateSource.SourceFiles.Count; Differences = $sourceDifferences }
        CandidatePatch = [ordered]@{ Path = 'candidate.patch'; Format = 'git diff --binary'; SHA256 = Get-Hash $patchPath; Text = $patchText; Files = @('JsonParser/JSON.cs', 'JsonParserのテスト/JSONのテスト.cs') }
    }
    BuildsAndTests = [ordered]@{
        ParentValidation = $parentValidation
        ParentValidationPath = Get-RelativePath $parentValidationPath
        ParentValidationSHA256 = Get-Hash $parentValidationPath
        Interpretation = 'Release full-solution build succeeded. All tests passed (311 total, including 63 JSON tests). Format diagnostics remained the same 66 existing diagnostics, with no new diagnostics on changed lines; format command exit code 2 is retained rather than represented as success.'
    }
    Input = [ordered]@{ Path = 'Kotowari.Benchmarks/Data/test.json'; Bytes = 4172062; SHA256 = $inputHash; ExpectedNodeCount = 100001 }
    FrozenHosts = [ordered]@{
        DLLCountPerVariant = 28
        DLLManifestPath = 'dll-manifest.json'
        DLLManifestSHA256 = Get-Hash $dllManifestPath
        DLLManifest = $dllManifest
        DLLDifferences = $dllDifferences
        FixedLibrarySHA256 = '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8'
        BaselineParserSHA256 = '1075799C05DC787D354EFC931D3A641C5C4424561F91C401947DB8D018CA0ACB'
        CandidateParserSHA256 = 'BAD351B1D5A6673C2096A4D0C2E04C4C2743B73EBAF70E1135890AF9504F4418'
        HostValidation = [ordered]@{ Baseline = (Read-Json (Join-Path $root 'baseline/validation.json')); Candidate = (Read-Json (Join-Path $root 'candidate/validation.json')) }
        ValidationInterpretation = 'Both frozen hosts consumed the full 4,172,062-character input, produced 100,001 nodes, and matched the System.Text.Json tree.'
    }
    Workload = [ordered]@{
        Method = 'Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput'
        Description = 'MemoryStream creation/copy -> UTF-8 decode to string -> full JSON parse/tree creation'
        Runtime = $exploration.Runs[0].Summary.Runtime
        BenchmarkDotNet = $exploration.Runs[0].Summary.BenchmarkDotNet
        TieredPGO = 1; AffinityMask = 4; WarmupCount = 16; ActualCount = 8; ResultCount = 8; InvocationCount = 4; IterationCount = 8; LaunchCount = 1; UnrollFactor = 1; OutlierMode = 'DontRemove'
        InputBytes = 4172062; InputSHA256 = $inputHash; DLLManifestSHA256 = Get-Hash $dllManifestPath
        ProcessModel = 'Every launch used Process.Start and waited for exit; each launch ran in a fresh dotnet process.'
    }
    FormalExploration = $exploration
    IndependentConfirmation = $confirmation
    Environment = [ordered]@{
        Records = $environment
        EnvironmentSHA256 = Get-Hash $environmentPath
        PowerHelper = [ordered]@{
            StatusPath = Get-RelativePath $helperStatusPath
            StatusSHA256 = Get-Hash $helperStatusPath
            Status = $helperStatus
            HeartbeatPath = Get-RelativePath $helperHeartbeatPath
            HeartbeatSHA256 = Get-Hash $helperHeartbeatPath
            HeartbeatCount = $helperHeartbeats.Count
            LastHeartbeatUTC = $helperStatus.LastHeartbeatUtc
            Release = $null
        }
        Interpretation = 'Before/after records for both batches show AC power, Battery Saver off, and no active dotnet CPU process. The shared system-required power helper was confirmed active during measurement; its post-release state will be appended after parent cleanup.'
    }
    JITDiagnostic = [ordered]@{
        Records = $jitRecords
        Interpretation = 'JIT diagnostic only; excluded from timing statistics. Baseline Tier1 WithWhiteSpaceParser<char>.ParseCore contains an OrParser array loop and candidate CharParser checks. Candidate Tier1 has a single current-character path and predicate call; its Tier1 predicate recognizes TAB/LF/CR through a bitmap and SPACE separately. The delegate remains an indirect call in the separate ConditionalCharParser tiered method in this PGO profile; this is structural evidence, not an isolated speed attribution. Code-size difference is not treated as a time measurement.'
        Limitations = @('Current JIT profile also includes ConditionalCharParser uses such as digit parsing; shared delegate-type profile behavior may contribute.', 'No CPU sampling/allocation diagnostic was collected for this experiment.', 'Tier1 output depends on this runtime, input, and PGO profile.')
    }
    Replay = [ordered]@{
        Scripts = $replayScripts
        EvidenceBuilder = [ordered]@{ Path = 'Build-Evidence.ps1'; SHA256 = Get-Hash $PSCommandPath; HashScope = 'File bytes including any BOM'; Body = $builderText }
        RunSummaries = [ordered]@{
            ExplorationPath = 'exploration-summary.json'; ExplorationSHA256 = Get-Hash (Join-Path $root 'exploration-summary.json')
            ConfirmationPath = 'confirmation-summary.json'; ConfirmationSHA256 = Get-Hash (Join-Path $root 'confirmation-summary.json')
        }
    }
}
$json = ConvertTo-Json -InputObject $data -Depth 60
if ($json -match '(?i)[A-Z]:\\Users\\|[A-Z]:/Users/') { throw 'Evidence content contains a user-specific absolute path.' }
$utf8 = [Text.UTF8Encoding]::new($true)
$savedText = ($json -replace "`r?`n", "`r`n") + "`r`n"
[IO.File]::WriteAllBytes($output, $utf8.GetPreamble() + $utf8.GetBytes($savedText))
$savedBytes = [IO.File]::ReadAllBytes($output)
if ($savedBytes.Length -lt 4 -or $savedBytes[0] -ne 0xEF -or $savedBytes[1] -ne 0xBB -or $savedBytes[2] -ne 0xBF) { throw 'Evidence JSON is missing its UTF-8 BOM.' }
$text = [Text.UTF8Encoding]::new($false).GetString($savedBytes, 3, $savedBytes.Length - 3)
if ([regex]::Matches($text, "(?<!`r)`n").Count -ne 0 -or [regex]::Matches($text, "`r`n").Count -eq 0) { throw 'Evidence JSON line endings are not uniformly CRLF.' }
$loaded = ConvertFrom-Json -InputObject $text -DateKind String
if ($loaded.FormalExploration.PairCount -ne 8 -or $loaded.IndependentConfirmation.PairCount -ne 8 -or $loaded.FrozenHosts.HostValidation.Candidate.FullInputConsumed -ne $true) { throw 'Evidence JSON round-trip verification failed.' }
Write-Output ([ordered]@{
    Path = Get-RelativePath $output
    SHA256 = Get-Hash $output
    Bytes = $savedBytes.Length
    BOM = $true
    CRLF = [regex]::Matches($text, "`r`n").Count
    BareLF = [regex]::Matches($text, "(?<!`r)`n").Count
    ExplorationRatio = $loaded.FormalExploration.PairedGeometricMeanRatio
    ExplorationConfidence95 = $loaded.FormalExploration.Confidence95
    ConfirmationRatio = $loaded.IndependentConfirmation.PairedGeometricMeanRatio
    ConfirmationConfidence95 = $loaded.IndependentConfirmation.Confidence95
    Launches = $loaded.FormalExploration.Runs.Count + $loaded.IndependentConfirmation.Runs.Count
    PowerHelperReleased = $false
} | ConvertTo-Json -Depth 4 -Compress)
